function icon(name,cls='') { return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.server}"/></svg>`; }
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});}
hydrateIcons();

const STORAGE='netra.workspace.v1';
let maps=[],currentId,orgName='Моя организация',storageAvailable=true;
try {
  const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');
  if(saved && Array.isArray(saved.maps) && saved.maps.length){maps=saved.maps.slice(0,30).map(m=>({id:String(m.id),map:validateMap(m.map)}));currentId=maps.some(m=>m.id===saved.currentId)?saved.currentId:maps[0].id;orgName=String(saved.orgName||orgName).slice(0,70);}
}catch{storageAvailable=false;}
if(!maps.length){currentId=uid();maps=[{id:currentId,map:demoMap()}];}
let map=maps.find(m=>m.id===currentId).map;
let selected=map.nodes.some(n=>n.id==='core')?'core':map.nodes[0]?.id;
let view='topology',query='',statusFilter='all',typeFilter='all',showZones=true,showLabels=true,showIPs=true,tool='select',connectionFrom=null;
let undoStack=[],redoStack=[],camera={x:0,y:0,scale:1},inspectorTab='properties',drag=null,toastTimer;
const canvas=$('#networkCanvas'),scene=$('#scene');
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function persist(){maps.find(m=>m.id===currentId).map=map;try{localStorage.setItem(STORAGE,JSON.stringify({maps,currentId,orgName}));storageAvailable=true;$('#saveIndicator').innerHTML='<span class="status-dot online"></span>Сохранено в браузере';}catch{storageAvailable=false;$('#saveIndicator').innerHTML='<span class="status-dot warning"></span>Скачайте копию карты';} }
function checkpoint(){undoStack.push(clone(map));if(undoStack.length>60)undoStack.shift();redoStack=[];}
function commit(change){checkpoint();change();map.demo=false;persist();render();}
function undo(){if(!undoStack.length)return;redoStack.push(clone(map));map=undoStack.pop();if(!map.nodes.some(n=>n.id===selected))selected=null;persist();render();}
function redo(){if(!redoStack.length)return;undoStack.push(clone(map));map=redoStack.pop();persist();render();}
function matches(n){const q=query.toLocaleLowerCase('ru');return (!q||[n.name,n.ip,n.model,n.vlan,TYPES[n.type]].join(' ').toLocaleLowerCase('ru').includes(q))&&(statusFilter==='all'||n.status===statusFilter)&&(typeFilter==='all'||n.type===typeFilter);}
function renderSidebar(){
  $('#mapList').innerHTML=maps.map(m=>`<button class="map-link ${m.id===currentId?'active':''}" data-map-id="${esc(m.id)}"><span class="dot"></span><span class="map-link-name">${esc(m.map.name)}</span>${m.map.demo?'<small>ДЕМО</small>':''}</button>`).join('');
  $('#mapsCount').textContent=maps.length;$('#navCount').textContent=map.nodes.length;
  $('.workspace-switch strong').textContent=orgName;$('.breadcrumb>span:nth-child(3)').textContent=orgName;
  $$('#mapList [data-map-id]').forEach(b=>b.onclick=()=>switchMap(b.dataset.mapId));
}
function renderStats(){
  const online=map.nodes.filter(n=>n.status==='online').length, warning=map.nodes.filter(n=>n.status==='warning').length, offline=map.nodes.filter(n=>n.status==='offline').length;
  const stats=[['server','Всего устройств',map.nodes.length,'В вашей инфраструктуре',null],['activity','В работе',online,`${offline} отключено`,map.nodes.length?Math.round(online/map.nodes.length*100)+'% сети':'Пустая карта'],['link','Соединения',map.edges.length,'Кабельные и беспроводные',null],['layers','Подсети и VLAN',new Set(map.nodes.map(n=>n.vlan).filter(Boolean)).size,`${map.zones.length} зоны · ${warning} требуют внимания`,null]];
  $('#stats').innerHTML=stats.map((s,i)=>`<article class="stat-card"><div class="stat-label">${icon(s[0])}${s[1]}</div><div class="stat-bottom"><span class="stat-number">${s[2]}</span>${s[4]?`<span class="stat-detail">${s[4]}</span>`:`<span class="mini-bars" aria-hidden="true">${[12,19,15,24,19,27,23,30,26,32].map((h,j)=>`<i style="height:${h-((i+j)%3)*2}px"></i>`).join('')}</span>`}</div><p class="stat-caption">${s[3]}</p></article>`).join('');
}
const colors={green:{fill:'#f0f6e8',stroke:'#d5e3c7',text:'#83a36b'},purple:{fill:'#f5f2fa',stroke:'#e0d8ed',text:'#a28bb7'},amber:{fill:'#fcf7e9',stroke:'#e9ddba',text:'#b6a16a'},blue:{fill:'#eef5fa',stroke:'#cddfe9',text:'#7b9eb4'}};
