    storage:'<path d="m5 8 19-5 10 7-20 6Z" fill="#e0d8ed"/><path d="M5 8v23l9 8V16Z" fill="#c4b3d5"/><path d="m14 16 20-6v23l-20 6Z" fill="#ae97c7"/><path d="m18 19 12-3m-12 10 12-3m-12 10 12-3" stroke="#f5f0fa" stroke-width="2"/>',
