    wifi:'<path d="m4 27 16-8 16 8-16 9Z" fill="#eddfb7"/><path d="M4 27v4l16 9v-4Zm16 9 16-9v4l-16 9Z" fill="#c8b783"/><path d="M8 10a18 18 0 0 1 24 0M12 15a12 12 0 0 1 16 0m-12 5a6 6 0 0 1 8 0" fill="none" stroke="#c4aa64" stroke-width="2.4" stroke-linecap="round"/><circle cx="20" cy="25" r="2" fill="#c4aa64"/>',
    printer:'<path d="m5 14 22-4 9 6-23 5Z" fill="#dae6cf"/><path d="M5 14v17l8 6V21Z" fill="#b7cba7"/><path d="m13 21 23-5v16l-23 5Z" fill="#a7bf95"/><path d="m13 6 16-3v14l-16 3Zm2 21 16-3v13l-16 3Z" fill="#eef4e7"/><path d="m19 29 8-2m-8 5 8-2" stroke="#b9caaa" stroke-width="1.5"/>',
