function edgePath(edge){
  const a=map.nodes.find(n=>n.id===edge.from),b=map.nodes.find(n=>n.id===edge.to);if(!a||!b)return '';
  const ax=a.x+77,ay=a.y+76,bx=b.x+77,by=b.y;
  if(Math.abs(ax-bx)<3)return `M${ax} ${ay}V${by}`;
  if(by>ay+20){
    const zone=map.zones.find(z=>z.id===b.zone);
    if(a.id==='core'&&zone&&by>zone.y+100){const lane=zone.x+8;return `M${ax} ${ay}V${zone.y-17}H${lane}V${by-15}H${bx}V${by}`;}
    const mid=a.id==='core'&&zone?zone.y-17:Math.round((ay+by)/2);return `M${ax} ${ay}V${mid}H${bx}V${by}`;
  }
  return `M${a.x+154} ${a.y+38}H${Math.max(a.x,b.x)+177}V${b.y+38}H${b.x+154}`;
}
function renderScene(){
  const zoneMarkup=showZones?map.zones.map(z=>{const c=colors[z.color]||colors.green;const count=map.nodes.filter(n=>n.zone===z.id).length;return `<g><rect x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" rx="12" fill="${c.fill}" fill-opacity=".45" stroke="${c.stroke}" stroke-dasharray="5 5"/><circle cx="${z.x+19}" cy="${z.y+24}" r="3" fill="${c.text}"/><text class="zone-label" fill="${c.text}" x="${z.x+31}" y="${z.y+27}">${esc(z.name)}</text><text class="zone-description" fill="${c.text}" x="${z.x+16}" y="${z.y+46}" opacity=".8">${count} ${plural(count,'устройство','устройства','устройств')}</text></g>`;}).join(''):'';
  const edgeMarkup=map.edges.map(e=>{const a=map.nodes.find(n=>n.id===e.from),b=map.nodes.find(n=>n.id===e.to);const d=edgePath(e);return `<g opacity="${a&&b&&matches(a)&&matches(b)?1:.2}"><path d="${d}" class="edge-path ${e.kind==='wireless'?'wireless':''} ${a?.status==='offline'||b?.status==='offline'?'edge-offline':''}"/><path d="${d}" class="edge-hit" data-edge="${esc(e.id)}"/>${showLabels&&a&&b&&Math.abs(a.x-b.x)<3&&b.y>a.y?`<rect x="${a.x+84}" y="${(a.y+76+b.y)/2-7}" width="63" height="14" rx="4" fill="#fafbf7"/><text class="edge-label" x="${a.x+89}" y="${(a.y+76+b.y)/2+3}">${esc(e.speed)}</text>`:''}</g>`;}).join('');
  const nodeMarkup=map.nodes.map(n=>`<g class="node-group ${selected===n.id?'selected':''} ${matches(n)?'':'dimmed'} ${connectionFrom===n.id?'connect-from':''}" data-node="${esc(n.id)}" transform="translate(${n.x} ${n.y})" tabindex="0" role="button" aria-label="${esc(n.name)}, ${esc(TYPES[n.type])}, ${esc(n.ip)}, ${esc(STATUSES[n.status])}"><title>${esc(n.name)} · ${esc(n.ip)} · ${esc(STATUSES[n.status])}</title>${selected===n.id?'<rect class="node-selection" x="-4" y="-4" width="162" height="84" rx="11"/>':''}<rect class="node-card" width="154" height="76" rx="9"/>${equipmentGlyph(n.type,9,14)}<text class="node-title" x="47" y="28">${esc(n.name.length>17?n.name.slice(0,16)+'…':n.name)}</text>${showIPs?`<text class="node-ip" x="47" y="43">${esc(n.ip||'Внешняя сеть')}</text>`:''}<text class="node-kind" x="47" y="59">${esc(TYPES[n.type])}</text><circle cx="141" cy="12" r="2.7" fill="${{online:'#80a56e',warning:'#d1ac58',offline:'#abb2a2'}[n.status]}"/><circle class="node-port" cx="77" cy="0" r="2.5"/><circle class="node-port" cx="77" cy="76" r="2.5"/></g>`).join('');
  scene.innerHTML=zoneMarkup+edgeMarkup+nodeMarkup;applyCamera();
  $('#emptyState').hidden=map.nodes.length>0;
  const box=mapBounds();$('#minimapSvg').setAttribute('viewBox',`${box.x-20} ${box.y-20} ${box.w+40} ${box.h+40}`);
  $('#minimapSvg').innerHTML=map.edges.map(e=>`<path d="${edgePath(e)}" fill="none" stroke="#c0d0b4" stroke-width="5"/>`).join('')+map.nodes.map(n=>`<rect x="${n.x}" y="${n.y}" width="154" height="76" rx="9" fill="${n.id===selected?'#9bb887':'#dce7d2'}" stroke="#baccaa" stroke-width="3"/>`).join('');
}
function plural(n,one,few,many){return n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;}
function renderTable(){const nodes=map.nodes.filter(matches);$('#tableView').innerHTML=nodes.length?`<table class="device-table"><thead><tr><th>УСТРОЙСТВО</th><th>IP-АДРЕС</th><th>VLAN</th><th>СТАТУС</th></tr></thead><tbody>${nodes.map(n=>`<tr data-device="${esc(n.id)}" class="${selected===n.id?'selected':''}" tabindex="0"><td><div class="table-device">${icon(n.type)}<span><strong>${esc(n.name)}</strong><small>${esc(n.model||TYPES[n.type])}</small></span></div></td><td>${esc(n.ip||'—')}</td><td><span class="badge">${esc(n.vlan||'—')}</span></td><td>${statusBadge(n.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="no-results">Ничего не найдено. Попробуйте изменить поиск или фильтры.</div>';
  $$('#tableView [data-device]').forEach(el=>{el.onclick=()=>selectNode(el.dataset.device,true);el.onkeydown=e=>{if(e.key==='Enter')selectNode(el.dataset.device,true);};});
}
function renderSubnets(){const vlans=[...new Set(map.nodes.filter(matches).map(n=>n.vlan||'Без VLAN'))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));$('#subnetView').innerHTML=vlans.length?vlans.map(v=>{const nodes=map.nodes.filter(n=>(n.vlan||'Без VLAN')===v&&matches(n));const zone=map.zones.find(z=>z.id===nodes[0]?.zone);return `<article class="subnet-card"><div class="subnet-card-head"><h3>${v==='Без VLAN'?v:'VLAN '+esc(v)}</h3><span class="vlan-tag">${nodes.length} ${plural(nodes.length,'устройство','устройства','устройств')}</span></div><p>${esc(zone?.name||'Основная сеть')} · IP-адреса указаны в свойствах устройств</p><div class="subnet-devices">${nodes.map(n=>`<button data-device="${esc(n.id)}">${icon(n.type)}${esc(n.name)}</button>`).join('')}</div></article>`;}).join(''):'<div class="no-results">Подсети появятся после добавления устройств и назначения VLAN.</div>';
  $$('#subnetView [data-device]').forEach(el=>el.onclick=()=>selectNode(el.dataset.device,true));
}
function statusBadge(status){return `<span class="status-badge ${status}-status"><span class="status-dot ${status}"></span>${STATUSES[status]}</span>`;}
function renderInspector(){
  const n=map.nodes.find(n=>n.id===selected);if(!n){$('#inspector').innerHTML=`<div class="inspector-empty">${icon('cursor')}<h3>Каждая деталь важна</h3><p>Выберите устройство на карте, чтобы увидеть его свойства и соединения.</p><button class="btn" id="inspectorAdd">${icon('plus')}Добавить устройство</button></div>`;$('#inspectorAdd').onclick=()=>deviceModal();return;}
  const zone=map.zones.find(z=>z.id===n.zone),connections=map.edges.filter(e=>e.from===n.id||e.to===n.id);
  $('#inspector').innerHTML=`<div class="inspector-heading"><span>Свойства устройства</span><button class="icon-btn" id="closeInspector" aria-label="Закрыть свойства">${icon('close')}</button></div><div class="device-hero"><span class="device-large-icon">${icon(n.type)}</span><span><strong title="${esc(n.name)}">${esc(n.name)}</strong><small>${esc(TYPES[n.type])}</small></span></div>${statusBadge(n.status)}<div class="inspector-tabs"><button class="${inspectorTab==='properties'?'active':''}" data-inspector-tab="properties">Обзор</button><button class="${inspectorTab==='notes'?'active':''}" data-inspector-tab="notes">Заметки${n.notes?' ·':''}</button></div>${inspectorTab==='properties'?`<h3 class="property-title">ОСНОВНАЯ ИНФОРМАЦИЯ</h3><div class="property-row"><span>IP-адрес</span><strong class="mono">${esc(n.ip||'Не указан')}</strong></div><div class="property-row"><span>Модель</span><strong>${esc(n.model||'Не указана')}</strong></div><div class="property-row"><span>VLAN</span><strong class="vlan-tag">${esc(n.vlan?'VLAN '+n.vlan:'Не назначен')}</strong></div><div class="property-row"><span>Зона</span><strong>${esc(zone?.name||'Основная сеть')}</strong></div><div class="property-divider"></div><div class="connections-header"><h3 class="property-title">СОЕДИНЕНИЯ</h3><span>${connections.length}</span></div><div class="connection-list">${connections.slice(0,6).map(e=>{const other=map.nodes.find(o=>o.id===(e.from===n.id?e.to:e.from));return `<div class="connection-item">${icon('link')}<button data-inspector-node="${esc(other.id)}">${esc(other.name)}</button><button class="connection-speed" data-inspector-edge="${esc(e.id)}" aria-label="Изменить соединение с ${esc(other.name)}">${esc(e.speed)}</button></div>`;}).join('')}${connections.length>6?`<button class="connection-item" id="allConnections">Ещё ${connections.length-6} соединений ${icon('chevron-down')}</button>`:''}${!connections.length?'<p class="settings-note">Пока нет соединений</p>':''}</div><button class="tool-button" id="inspectorConnect" style="margin-top:10px;font-size:8px">${icon('plus')}Добавить соединение</button>`:`<h3 class="property-title">ЗАМЕТКИ ОБ УСТРОЙСТВЕ</h3><p class="notes-text">${esc(n.notes||'Добавьте расположение, назначение или другие важные детали устройства.')}</p>`}<button class="btn edit-btn" id="editSelected">${icon('edit')}Редактировать устройство</button><div class="inspector-bottom-note">Данные вашей схемы · ручное управление</div>`;
  $('#closeInspector').onclick=()=>{$('#inspector').classList.remove('mobile-open');selected=null;renderScene();renderInspector();};
  $('#editSelected').onclick=()=>deviceModal(n.id);$$('[data-inspector-tab]').forEach(b=>b.onclick=()=>{inspectorTab=b.dataset.inspectorTab;renderInspector();});
  $$('[data-inspector-node]').forEach(b=>b.onclick=()=>selectNode(b.dataset.inspectorNode));$$('[data-inspector-edge]').forEach(b=>b.onclick=()=>edgeModal(b.dataset.inspectorEdge));
  if($('#inspectorConnect'))$('#inspectorConnect').onclick=()=>edgeModal(null,n.id);
  if($('#allConnections'))$('#allConnections').onclick=()=>connectionsModal(n);
}
function render(){
  renderSidebar();renderStats();$('#mapTitle').innerHTML=`${esc(map.name)}${icon('chevron-down')}`;$('#demoBadge').hidden=!map.demo;$('#canvasLabel').textContent=map.name;$('#deviceTabCount').textContent=map.nodes.length;$('#undo').disabled=!undoStack.length;$('#redo').disabled=!redoStack.length;$('#filterDot').hidden=statusFilter==='all'&&typeFilter==='all';renderScene();renderInspector();if(view==='devices')renderTable();if(view==='subnets')renderSubnets();
}
function selectNode(id,mobile=false){selected=id;renderScene();renderInspector();if(view==='devices')renderTable();if(mobile||window.innerWidth<881)$('#inspector').classList.add('mobile-open');}
function setView(next){view=next;closePopover();$$('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));$('#canvasView').hidden=view!=='topology';$('#tableView').hidden=view!=='devices';$('#subnetView').hidden=view!=='subnets';if(view==='devices')renderTable();if(view==='subnets')renderSubnets();if(view==='topology')requestAnimationFrame(fitCamera);$('#sidebar').classList.remove('open');}
function mapBounds(){const xs=map.nodes.map(n=>n.x),ys=map.nodes.map(n=>n.y);if(showZones)map.zones.forEach(z=>{xs.push(z.x,z.x+z.w-154);ys.push(z.y,z.y+z.h-76);});if(!xs.length)return{x:0,y:0,w:1060,h:830};const x=Math.min(...xs),y=Math.min(...ys);return {x,y,w:Math.max(...xs)-x+154,h:Math.max(...ys)-y+76};}
function applyCamera(){scene.setAttribute('transform',`translate(${camera.x} ${camera.y}) scale(${camera.scale})`);$('#zoomValue').textContent=Math.round(camera.scale*100)+'%';}
function fitCamera(){if(view!=='topology')return;const {width,height}=canvas.getBoundingClientRect();if(!width||!height)return;const b=mapBounds(),space=height-105;camera.scale=Math.min(1.3,Math.max(.18,Math.min((width-44)/(b.w+40),space/(b.h+30))));camera.x=(width-b.w*camera.scale)/2-b.x*camera.scale;camera.y=46+(space-b.h*camera.scale)/2-b.y*camera.scale;applyCamera();}
function zoom(factor,px,py){const r=canvas.getBoundingClientRect();const x=px??r.width/2,y=py??r.height/2;const s=Math.max(.15,Math.min(2.5,camera.scale*factor));camera.x=x-(x-camera.x)*s/camera.scale;camera.y=y-(y-camera.y)*s/camera.scale;camera.scale=s;applyCamera();}
function setTool(next){tool=next;connectionFrom=null;$('#canvasView').classList.toggle('panning',next==='hand');$('#canvasView').classList.toggle('connecting',next==='connect');$('#selectTool').classList.toggle('active',next==='select');$('#handTool').classList.toggle('active',next==='hand');$('#connectTool').classList.toggle('active',next==='connect');$('#connectionHint').hidden=next!=='connect';$('#connectionHint').textContent='Выберите первое устройство · Esc для отмены';renderScene();}
canvas.addEventListener('pointerdown',e=>{
  if(e.button!==0&&e.button!==1)return;closePopover();const node=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]');
  if(tool==='connect'&&node){const id=node.dataset.node;if(!connectionFrom){connectionFrom=id;$('#connectionHint').textContent='Теперь выберите второе устройство';renderScene();}else if(id!==connectionFrom){edgeModal(null,connectionFrom,id);setTool('select');}return;}
  if(edge&&!node&&tool==='select'){edgeModal(edge.dataset.edge);return;}
  if(node&&tool==='select'&&e.button===0){selected=node.dataset.node;const n=map.nodes.find(n=>n.id===selected);drag={kind:'node',id:selected,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,moved:false,old:clone(map)};renderScene();renderInspector();}
  else drag={kind:'pan',startX:e.clientX,startY:e.clientY,x:camera.x,y:camera.y,moved:false};
  canvas.setPointerCapture(e.pointerId);e.preventDefault();
});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;if(!drag.moved)return;if(drag.kind==='pan'){camera.x=drag.x+dx;camera.y=drag.y+dy;applyCamera();}else{const n=map.nodes.find(n=>n.id===drag.id);n.x=Math.round((drag.x+dx/camera.scale)/5)*5;n.y=Math.round((drag.y+dy/camera.scale)/5)*5;renderScene();}});
function endDrag(e){if(!drag)return;const d=drag;drag=null;if(d.kind==='node'){if(d.moved){undoStack.push(d.old);if(undoStack.length>60)undoStack.shift();redoStack=[];map.demo=false;persist();render();}else if(window.innerWidth<881)$('#inspector').classList.add('mobile-open');}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);}
canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);
canvas.addEventListener('dblclick',e=>{const n=e.target.closest('[data-node]');if(n)deviceModal(n.dataset.node);});
canvas.addEventListener('keydown',e=>{const n=e.target.closest('[data-node]');if(n&&e.key==='Enter'){selectNode(n.dataset.node,true);e.preventDefault();}});
canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();if(e.ctrlKey||e.metaKey)zoom(Math.exp(-e.deltaY*.008),e.clientX-r.left,e.clientY-r.top);else{camera.x-=e.deltaX;camera.y-=e.deltaY;applyCamera();}},{passive:false});

function closePopover(){$('#popover').hidden=true;$('#popover').innerHTML='';}
function popover(anchor,content){const p=$('#popover');p.innerHTML=content;p.hidden=false;const r=anchor.getBoundingClientRect();p.style.left=Math.max(10,Math.min(r.left,window.innerWidth-p.offsetWidth-12))+'px';p.style.top=Math.min(r.bottom+7,window.innerHeight-p.offsetHeight-10)+'px';}
function menu(anchor,items){popover(anchor,items.map((item,i)=>item===null?'<hr>':`<button data-menu-action="${i}">${icon(item.icon)}${esc(item.label)}</button>`).join(''));$$('[data-menu-action]').forEach(b=>b.onclick=()=>{const action=items[Number(b.dataset.menuAction)].action;closePopover();action();});}
document.addEventListener('pointerdown',e=>{if(!$('#popover').hidden&&!$('#popover').contains(e.target)&&!e.target.closest('#exportButton,#mapTitle,#moreActions,#filterButton,#layersButton'))closePopover();});
function openModal(title,body,footer=''){closePopover();$('#modalContent').innerHTML=`<div class="modal-header"><h2 id="modalTitle">${esc(title)}</h2><button class="icon-btn" data-close-modal aria-label="Закрыть">${icon('close')}</button></div>${body}${footer}`;$$('[data-close-modal]').forEach(b=>b.onclick=()=>$('#modal').close());if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>$('#modal input:not([type=hidden]),#modal select,#modal textarea')?.focus(),50);}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
function formError(message){let el=$('#formError');if(el){el.textContent=message;el.hidden=false;}}
function options(values,current){return Object.entries(values).map(([value,label])=>`<option value="${esc(value)}" ${String(current)===String(value)?'selected':''}>${esc(label)}</option>`).join('');}
function deviceModal(id){
  const existing=map.nodes.find(n=>n.id===id);const center={x:Math.round((canvas.clientWidth/2-camera.x)/camera.scale-77),y:Math.round((canvas.clientHeight/2-camera.y)/camera.scale-38)};
  const n=existing||{name:'',type:'switch',ip:'',vlan:'',zone:'core',status:'online',model:'',notes:'',...center};
  openModal(existing?'Редактировать устройство':'Новое устройство',`<form id="deviceForm"><div class="modal-body"><div id="formError" class="modal-error" hidden></div><div class="form-grid"><label class="field full">Название устройства<input name="name" value="${esc(n.name)}" placeholder="Например, Core-Switch-02" maxlength="80" required></label><label class="field">Тип устройства<select name="type">${options(TYPES,n.type)}</select></label><label class="field">Статус<select name="status">${options(STATUSES,n.status)}</select></label><label class="field">IP-адрес (IPv4)<input name="ip" value="${esc(n.ip)}" placeholder="192.168.1.10" inputmode="decimal"></label><label class="field">VLAN<input name="vlan" value="${esc(n.vlan)}" placeholder="Например, 10" maxlength="30"></label><label class="field full">Модель оборудования<input name="model" value="${esc(n.model)}" placeholder="Производитель и модель" maxlength="150"></label><label class="field full">Зона<select name="zone">${options({core:'Основная сеть',...Object.fromEntries(map.zones.map(z=>[z.id,z.name]))},n.zone)}</select></label><label class="field full">Заметки<textarea name="notes" maxlength="1500" placeholder="Расположение, назначение, важные детали…">${esc(n.notes)}</textarea></label></div></div><div class="modal-footer">${existing?`<button type="button" class="delete-device" id="deleteDevice">Удалить</button>`:''}<button type="button" class="btn" data-close-modal>Отмена</button><button type="submit" class="btn primary">${existing?'Сохранить изменения':'Добавить устройство'}</button></div></form>`);
  $('#deviceForm').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));values.name=values.name.trim();values.ip=values.ip.trim();values.vlan=values.vlan.trim();if(!values.name)return formError('Укажите название устройства.');if(!validIP(values.ip))return formError('Введите корректный IPv4-адрес, например 192.168.1.10.');if(values.vlan&&(!/^\d+$/.test(values.vlan)||+values.vlan<1||+values.vlan>4094))return formError('Номер VLAN должен быть от 1 до 4094.');if(map.nodes.some(o=>o.id!==id&&values.ip&&o.ip===values.ip))return formError('Устройство с таким IP-адресом уже есть на карте.');if(!existing&&map.nodes.length>=500)return formError('На одной карте поддерживается до 500 устройств.');
    commit(()=>{if(existing)Object.assign(existing,values);else{const node={...n,...values,id:uid()};const zone=map.zones.find(z=>z.id===node.zone);if(zone){node.x=zone.x+18;node.y=zone.y+66;}map.nodes.push(node);selected=node.id;}});$('#modal').close();notify(existing?'Свойства устройства обновлены':'Устройство добавлено на карту');
  };
  if($('#deleteDevice'))$('#deleteDevice').onclick=()=>confirmDeleteDevice(existing);
}
function confirmDeleteDevice(n){const count=map.edges.filter(e=>e.from===n.id||e.to===n.id).length;openModal('Удалить устройство?',`<div class="modal-body"><p>«${esc(n.name)}» будет удалено с карты${count?` вместе с соединениями (${count})`:''}. Действие можно отменить сочетанием Ctrl+Z.</p></div>`,`<div class="modal-footer"><button class="btn" data-close-modal>Отмена</button><button class="btn danger" id="confirmDelete">Удалить устройство</button></div>`);$('#confirmDelete').onclick=()=>{commit(()=>{map=removeNode(map,n.id);selected=null;});$('#modal').close();notify('Устройство удалено');};}
function edgeModal(id,from,to){
  if(map.nodes.length<2){notify('Сначала добавьте хотя бы два устройства');return;}
  const edge=map.edges.find(e=>e.id===id)||{from:from||selected||map.nodes[0].id,to:to||map.nodes.find(n=>n.id!==(from||selected||map.nodes[0].id)).id,speed:'1 Гбит/с',kind:'ethernet'};
  const nodeOptions=Object.fromEntries(map.nodes.map(n=>[n.id,n.name+(n.ip?' · '+n.ip:'')]));
  openModal(id?'Свойства соединения':'Новое соединение',`<form id="edgeForm"><div class="modal-body"><div id="formError" class="modal-error" hidden></div><p>Выберите два устройства и укажите параметры связи.</p><div class="form-grid"><label class="field full">Первое устройство<select name="from">${options(nodeOptions,edge.from)}</select></label><label class="field full">Второе устройство<select name="to">${options(nodeOptions,edge.to)}</select></label><label class="field">Тип соединения<select name="kind">${options({ethernet:'Кабельное',wireless:'Беспроводное'},edge.kind)}</select></label><label class="field">Скорость / подпись<input name="speed" value="${esc(edge.speed)}" maxlength="40" placeholder="1 Гбит/с" required></label></div></div><div class="modal-footer">${id?'<button type="button" class="delete-device" id="deleteEdge">Удалить</button>':''}<button type="button" class="btn" data-close-modal>Отмена</button><button class="btn primary" type="submit">${id?'Сохранить':'Соединить'}</button></div></form>`);
  $('#edgeForm').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(values.from===values.to)return formError('Выберите два разных устройства.');if(map.edges.some(e=>e.id!==id&&((e.from===values.from&&e.to===values.to)||(e.from===values.to&&e.to===values.from))))return formError('Эти устройства уже соединены. Нажмите на линию, чтобы изменить связь.');commit(()=>{if(id)Object.assign(edge,values);else map.edges.push({id:uid(),...values});});$('#modal').close();notify(id?'Соединение обновлено':'Соединение создано');};
  if($('#deleteEdge'))$('#deleteEdge').onclick=()=>{commit(()=>{map.edges=map.edges.filter(e=>e.id!==id);});$('#modal').close();notify('Соединение удалено');};
}
function connectionsModal(n){const edges=map.edges.filter(e=>e.from===n.id||e.to===n.id);openModal('Соединения · '+n.name,`<div class="modal-body">${edges.map(e=>{const other=map.nodes.find(o=>o.id===(e.from===n.id?e.to:e.from));return `<button class="modal-choice" data-edit-edge="${esc(e.id)}">${icon('link')}<span><strong>${esc(other.name)}</strong><small>${esc(e.speed)} · ${e.kind==='wireless'?'Беспроводное':'Кабельное'}</small></span></button>`;}).join('')}</div>`);$$('[data-edit-edge]').forEach(b=>b.onclick=()=>edgeModal(b.dataset.editEdge));}
function zoneModal(){openModal('Новая зона',`<form id="zoneForm"><div class="modal-body"><p>Группируйте устройства по отделам, помещениям или назначению. Зону можно назначить в свойствах устройства.</p><div class="form-grid"><label class="field full">Название зоны<input name="name" placeholder="Например, Бухгалтерия" maxlength="60" required></label><label class="field full">Цвет<select name="color">${options({green:'Шалфейный',purple:'Лавандовый',amber:'Песочный',blue:'Голубой'},'green')}</select></label></div></div><div class="modal-footer"><button type="button" class="btn" data-close-modal>Отмена</button><button class="btn primary">Создать зону</button></div></form>`);$('#zoneForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.name.trim())return;const right=Math.max(0,...map.zones.map(z=>z.x+z.w),...map.nodes.map(n=>n.x+154));commit(()=>map.zones.push({id:uid(),name:v.name.trim(),color:v.color,x:right+30,y:408,w:345,h:345}));$('#modal').close();fitCamera();notify('Зона добавлена. Назначьте её устройствам в свойствах.');};}
function switchMap(id){if(id===currentId){$('#modal').close();return;}persist();currentId=id;map=maps.find(m=>m.id===id).map;selected=map.nodes[0]?.id;undoStack=[];redoStack=[];query='';$('#search').value='';statusFilter='all';typeFilter='all';setTool('select');persist();render();fitCamera();$('#sidebar').classList.remove('open');$('#inspector').classList.remove('mobile-open');if($('#modal').open)$('#modal').close();}
function createMap(demo=false,name){if(maps.length>=30){notify('Поддерживается до 30 карт. Экспортируйте и удалите ненужную карту.');return;}const id=uid();const m=demo?demoMap():{version:1,name:name||'Новая карта',demo:false,nodes:[],edges:[],zones:[]};maps.push({id,map:m});switchMap(id);setView('topology');notify('Новая карта создана');}
function newMapModal(){openModal('Создать карту сети',`<form id="newMapForm"><div class="modal-body"><p>Начните с чистого полотна или используйте готовый пример офисной сети.</p><label class="field">Название карты<input name="name" value="Новая карта" maxlength="100" required></label><label class="toggle-line" style="margin-top:13px">Заполнить демонстрационной сетью<input name="demo" type="checkbox"></label></div><div class="modal-footer"><button type="button" class="btn" data-close-modal>Отмена</button><button class="btn primary">Создать карту</button></div></form>`);$('#newMapForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('name').trim())return;createMap(f.has('demo'),f.get('name').trim());if(f.has('demo')){map.name=f.get('name').trim();persist();render();}$('#modal').close();};}
function renameMap(){textModal('Название карты','Название',map.name,value=>{commit(()=>map.name=value);notify('Название карты изменено');});}
function textModal(title,label,value,callback){openModal(title,`<form id="textForm"><div class="modal-body"><label class="field">${esc(label)}<input name="value" value="${esc(value)}" maxlength="100" required></label></div><div class="modal-footer"><button type="button" class="btn" data-close-modal>Отмена</button><button class="btn primary">Сохранить</button></div></form>`);$('#textForm').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('value').trim();if(!value)return;callback(value);$('#modal').close();};}
function mapsModal(){openModal('Мои карты',`<div class="modal-body"><p>Карты сохраняются в этом браузере. Для переноса на другое устройство используйте экспорт JSON.</p>${maps.map(m=>`<div class="map-management-row"><button data-open-map="${esc(m.id)}"><strong>${esc(m.map.name)}${m.id===currentId?' · текущая':''}</strong><small>${m.map.nodes.length} устройств · ${m.map.edges.length} соединений</small></button><button class="icon-btn" data-delete-map="${esc(m.id)}" aria-label="Удалить карту ${esc(m.map.name)}">${icon('trash')}</button></div>`).join('')}</div>`,`<div class="modal-footer"><button class="btn" id="modalImport">${icon('upload')}Импорт</button><button class="btn primary" id="modalNewMap">${icon('plus')}Создать карту</button></div>`);$$('[data-open-map]').forEach(b=>b.onclick=()=>{if(b.dataset.openMap===currentId)$('#modal').close();else switchMap(b.dataset.openMap);});$$('[data-delete-map]').forEach(b=>b.onclick=()=>deleteMapModal(b.dataset.deleteMap));$('#modalImport').onclick=()=>$('#importFile').click();$('#modalNewMap').onclick=newMapModal;}
function deleteMapModal(id){const entry=maps.find(m=>m.id===id);openModal('Удалить карту?',`<div class="modal-body"><div class="map-delete-warning">Карта «${esc(entry.map.name)}» будет удалена из этого браузера. Перед удалением рекомендуем экспортировать JSON. Отменить удаление карты нельзя.</div></div>`,`<div class="modal-footer"><button class="btn" data-close-modal>Отмена</button><button class="btn danger" id="confirmDeleteMap">Удалить карту</button></div>`);$('#confirmDeleteMap').onclick=()=>{maps=maps.filter(m=>m.id!==id);if(!maps.length){const replacement={id:uid(),map:{version:1,name:'Новая карта',nodes:[],edges:[],zones:[]}};maps.push(replacement);}if(id===currentId){currentId=maps[0].id;map=maps[0].map;selected=null;undoStack=[];redoStack=[];}persist();render();fitCamera();$('#modal').close();notify('Карта удалена');};}
function duplicateMap(){if(maps.length>=30){notify('Достигнут лимит: 30 карт');return;}const entry={id:uid(),map:clone(map)};entry.map.name=map.name+' — копия';entry.map.demo=false;maps.push(entry);switchMap(entry.id);notify('Создана копия карты');}
function mapMenu(anchor){menu(anchor,[{icon:'edit',label:'Переименовать карту',action:renameMap},{icon:'copy',label:'Создать копию',action:duplicateMap},null,{icon:'plus',label:'Новая карта',action:newMapModal},{icon:'upload',label:'Импортировать JSON',action:()=>$('#importFile').click()},{icon:'folder',label:'Все мои карты',action:mapsModal}]);}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function filename(ext){return (map.name.replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').trim()||'network')+'.'+ext;}
function exportJSON(){download(JSON.stringify({...map,version:1},null,2),filename('json'),'application/json');notify('Карта экспортирована в JSON');}
function exportSVG(){const b=mapBounds();const css=`.node-card{fill:#fff;stroke:#bcccaf;stroke-width:1}.node-selection{fill:none;stroke:#7a9f66;stroke-dasharray:3 3}.node-title{font:550 10px sans-serif;fill:#4b6040}.node-ip{font:8px monospace;fill:#8a9b7c}.node-kind{font:7px sans-serif;fill:#98a68c}.node-port{fill:#fff;stroke:#9db18d}.zone-label{font:500 10px sans-serif}.zone-description{font:8px sans-serif}.edge-path{fill:none;stroke:#b6c9a8;stroke-width:1.4}.wireless,.edge-offline{stroke-dasharray:4 4}.edge-hit{display:none}.edge-label{font:7px sans-serif;fill:#8a9e7b}.dimmed{opacity:1}`;const content=scene.innerHTML.replace(/ tabindex="0"/g,'');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${b.w+80}" height="${b.h+110}" viewBox="${b.x-40} ${b.y-65} ${b.w+80} ${b.h+110}"><style>${css}</style><rect x="${b.x-40}" y="${b.y-65}" width="100%" height="100%" fill="#fafbf7"/><text x="${b.x}" y="${b.y-28}" font-family="sans-serif" font-size="18" fill="#45613b">${esc(map.name)} · netra.</text>${content}</svg>`;download(svg,filename('svg'),'image/svg+xml');notify('Схема экспортирована в SVG');}
function exportCSV(){const rows=[['Название','Тип','IP-адрес','VLAN','Статус','Модель','Зона'],...map.nodes.map(n=>[n.name,TYPES[n.type],n.ip,n.vlan,STATUSES[n.status],n.model,map.zones.find(z=>z.id===n.zone)?.name||'Основная сеть'])];const cell=v=>{const s=String(v??'');return '"'+(/^[=+@\-\t\r]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"';};download('\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),filename('csv'),'text/csv;charset=utf-8');notify('Список оборудования экспортирован');}
$('#importFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>3*1024*1024){notify('Файл слишком большой. Максимум 3 МБ.');return;}try{const imported=validateMap(JSON.parse(await file.text()));if(maps.length>=30)throw new Error('Достигнут лимит: 30 карт.');const entry={id:uid(),map:imported};maps.push(entry);switchMap(entry.id);setView('topology');$('#modal').close();notify('Карта успешно импортирована');}catch(error){notify(error instanceof SyntaxError?'Не удалось прочитать JSON. Проверьте файл.':error.message);}};
function showHelp(){openModal('Ваша сеть — на одной карте',`<div class="modal-body"><ul class="help-list"><li>${icon('plus')}<span><b>Добавьте оборудование.</b><br>Выберите тип устройства, задайте IP-адрес, VLAN и расположение.</span></li><li>${icon('cursor')}<span><b>Расположите устройства на карте.</b><br>Перетаскивайте карточки. Двойной щелчок открывает редактирование.</span></li><li>${icon('link')}<span><b>Покажите соединения.</b><br>Нажмите на цепочку внизу и выберите два устройства. Щелчок по линии открывает её параметры.</span></li><li>${icon('layers')}<span><b>Организуйте сеть.</b><br>Добавляйте цветные зоны и назначайте VLAN в свойствах устройств.</span></li><li>${icon('download')}<span><b>Сохраните копию.</b><br>JSON позволяет перенести карту, SVG — вставить схему в документ, CSV — открыть список оборудования в таблице.</span></li></ul><p style="font-size:10px;margin-bottom:0">Это редактор схем. Он не подключается к оборудованию и не проверяет доступность. Статусы назначаются вручную; карты сохраняются только в этом браузере.</p></div>`,`<div class="modal-footer"><button class="btn" id="helpShortcuts">Горячие клавиши</button><button class="btn primary" data-close-modal>Понятно, начнём</button></div>`);$('#helpShortcuts').onclick=showShortcuts;}
function showShortcuts(){openModal('Горячие клавиши',`<div class="modal-body">${[['Выбрать устройство','V'],['Перемещать полотно','H'],['Соединить устройства','C'],['Найти устройство','/'],['Отменить действие','Ctrl / ⌘ + Z'],['Повторить действие','Ctrl / ⌘ + Shift + Z'],['Редактировать выбранное','Enter'],['Удалить выбранное','Delete'],['Увеличить / уменьшить','+ / −'],['Показать всю карту','0'],['Масштаб под курсором','Ctrl / ⌘ + прокрутка'],['Перемещение полотна','Прокрутка / перетаскивание'],['Сбросить инструмент','Esc']].map(r=>`<div class="shortcut-row"><span>${r[0]}</span><kbd>${r[1]}</kbd></div>`).join('')}</div>`);}
function settingsModal(){openModal('Ваше пространство',`<div class="modal-body"><label class="field">Название организации<input id="orgNameInput" value="${esc(orgName)}" maxlength="70"></label><p class="settings-note" style="margin-top:20px">Карты сохраняются автоматически в локальном хранилище браузера. При очистке данных браузера они удалятся. Экспортируйте JSON для резервного копирования или переноса на другое устройство.</p><div class="property-row"><span>Карт в пространстве</span><strong>${maps.length}</strong></div><div class="property-row"><span>Локальное сохранение</span><strong>${storageAvailable?'Доступно':'Недоступно — экспортируйте карту'}</strong></div></div>`,`<div class="modal-footer"><button class="btn" data-close-modal>Закрыть</button><button class="btn primary" id="saveOrg">Сохранить</button></div>`);$('#saveOrg').onclick=()=>{orgName=$('#orgNameInput').value.trim()||'Моя организация';persist();renderSidebar();$('#modal').close();notify('Название организации сохранено');};}

$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-nav]').forEach(b=>b.onclick=()=>setView(b.dataset.nav));
$('#addDevice').onclick=()=>deviceModal();$('#emptyAdd').onclick=()=>deviceModal();$('#quickNew').onclick=newMapModal;$('#allMaps').onclick=mapsModal;$('#mapTitle').onclick=e=>mapMenu(e.currentTarget);$('#moreActions').onclick=e=>mapMenu(e.currentTarget);
$('#exportButton').onclick=e=>menu(e.currentTarget,[{icon:'file',label:'Карта в JSON',action:exportJSON},{icon:'image',label:'Схема в SVG',action:exportSVG},{icon:'list',label:'Оборудование в CSV',action:exportCSV},null,{icon:'upload',label:'Импортировать JSON',action:()=>$('#importFile').click()}]);
$('#search').oninput=e=>{query=e.target.value;renderScene();if(view==='devices')renderTable();if(view==='subnets')renderSubnets();};
$('#filterButton').onclick=e=>{popover(e.currentTarget,`<div class="menu-title">СТАТУС УСТРОЙСТВА</div><label><select id="statusSelect" style="width:100%;padding:7px;border:1px solid #dfe6d7;border-radius:5px;background:#fafcf6;color:#617953">${options({all:'Все статусы',...STATUSES},statusFilter)}</select></label><div class="menu-title">ТИП УСТРОЙСТВА</div><label><select id="typeSelect" style="width:100%;padding:7px;border:1px solid #dfe6d7;border-radius:5px;background:#fafcf6;color:#617953">${options({all:'Все устройства',...TYPES},typeFilter)}</select></label><button id="resetFilters">${icon('close')}Сбросить фильтры</button>`);const refresh=()=>{statusFilter=$('#statusSelect').value;typeFilter=$('#typeSelect').value;render();};$('#statusSelect').onchange=refresh;$('#typeSelect').onchange=refresh;$('#resetFilters').onclick=()=>{statusFilter='all';typeFilter='all';query='';$('#search').value='';render();closePopover();};};
$('#layersButton').onclick=e=>{popover(e.currentTarget,`<div class="menu-title">ОТОБРАЖЕНИЕ КАРТЫ</div><label><input type="checkbox" id="zoneLayer" ${showZones?'checked':''}>Зоны сети</label><label><input type="checkbox" id="labelLayer" ${showLabels?'checked':''}>Подписи соединений</label><label><input type="checkbox" id="ipLayer" ${showIPs?'checked':''}>IP-адреса</label><hr><button id="manageZones">${icon('zone')}Управление зонами</button>`);$('#zoneLayer').onchange=e=>{showZones=e.target.checked;renderScene();};$('#labelLayer').onchange=e=>{showLabels=e.target.checked;renderScene();};$('#ipLayer').onchange=e=>{showIPs=e.target.checked;renderScene();};$('#manageZones').onclick=manageZones;};
function manageZones(){openModal('Зоны сети',`<div class="modal-body"><p>Устройства можно назначить зоне в их свойствах. Удаление зоны сохраняет оборудование и соединения.</p>${map.zones.length?map.zones.map(z=>`<div class="map-management-row"><button data-rename-zone="${esc(z.id)}"><strong>${esc(z.name)}</strong><small>${map.nodes.filter(n=>n.zone===z.id).length} устройств · нажмите, чтобы переименовать</small></button><button class="icon-btn" data-delete-zone="${esc(z.id)}" aria-label="Удалить зону ${esc(z.name)}">${icon('trash')}</button></div>`).join(''):'<p>Зон пока нет. Создайте первую.</p>'}</div>`,`<div class="modal-footer"><button class="btn" data-close-modal>Закрыть</button><button class="btn primary" id="newZone">${icon('plus')}Добавить зону</button></div>`);$('#newZone').onclick=zoneModal;$$('[data-delete-zone]').forEach(b=>b.onclick=()=>{commit(()=>{map.zones=map.zones.filter(z=>z.id!==b.dataset.deleteZone);map.nodes.forEach(n=>{if(n.zone===b.dataset.deleteZone)n.zone='core';});});manageZones();notify('Зона удалена. Устройства сохранены.');});$$('[data-rename-zone]').forEach(b=>b.onclick=()=>{const z=map.zones.find(z=>z.id===b.dataset.renameZone);textModal('Название зоны','Название',z.name,value=>commit(()=>z.name=value));});}
$('#undo').onclick=undo;$('#redo').onclick=redo;$('#selectTool').onclick=()=>setTool('select');$('#handTool').onclick=()=>setTool('hand');$('#connectTool').onclick=()=>setTool(tool==='connect'?'select':'connect');$('#addZone').onclick=zoneModal;$('#zoomIn').onclick=()=>zoom(1.2);$('#zoomOut').onclick=()=>zoom(1/1.2);$('#zoomValue').onclick=()=>{camera.scale=1;fitCamera();};$('#fitView').onclick=fitCamera;$('#minimap').onclick=fitCamera;
$('#helpButton').onclick=showHelp;$('#topHelp').onclick=showHelp;$('#shortcutButton').onclick=showShortcuts;$('#workspaceSwitch').onclick=settingsModal;$('#profileButton').onclick=settingsModal;$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('.brand').onclick=e=>{e.preventDefault();setView('topology');};
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){closePopover();setTool('select');$('#sidebar').classList.remove('open');$('#inspector').classList.remove('mobile-open');return;}
  if($('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable)return;
  const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.ctrlKey||e.metaKey)&&key==='y'){e.preventDefault();redo();return;}if(e.ctrlKey||e.metaKey||e.altKey)return;
  if(e.key==='/'){e.preventDefault();$('#search').focus();}else if(key==='v')setTool('select');else if(key==='h')setTool('hand');else if(key==='c')setTool('connect');else if(e.key==='0')fitCamera();else if(e.key==='+'||e.key==='=')zoom(1.2);else if(e.key==='-')zoom(1/1.2);else if(e.key==='Enter'&&selected&&!e.target.closest('button'))deviceModal(selected);else if((e.key==='Delete'||e.key==='Backspace')&&selected){e.preventDefault();confirmDeleteDevice(map.nodes.find(n=>n.id===selected));}
});
let resizeTimer;new ResizeObserver(()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(fitCamera,100);}).observe($('#canvasView'));
render();persist();requestAnimationFrame(fitCamera);
